update known_safe_harbors set tissue_context = 'hESCs/iPSCs (robust); silencing risk after differentiation into cardiomyocytes, endothelial cells, myeloid cells, hepatocytes, and Jurkat T cells' where source_pmid = '41511364' and evidence_summary = 'Cytogenetic band 19q13.4, intron 1 of PPP1R12C. Robust expression in hESCs/iPSCs without compromising pluripotency, but risk of silencing in cardiomyocytes, endothelial cells, myeloid cells, and hepatocytes, and in Jurkat T cells. Disrupts expression of PPP1R12C, TNNI3, and PPP6R1 (dense gene region). Via secondary review, not verified against the primary article.';
update public_safe_harbors_staging set tissue_context = 'hESCs/iPSCs (robust); silencing risk after differentiation into cardiomyocytes, endothelial cells, myeloid cells, hepatocytes, and Jurkat T cells' where source_pmid = '41511364' and evidence_summary = 'Cytogenetic band 19q13.4, intron 1 of PPP1R12C. Robust expression in hESCs/iPSCs without compromising pluripotency, but risk of silencing in cardiomyocytes, endothelial cells, myeloid cells, and hepatocytes, and in Jurkat T cells. Disrupts expression of PPP1R12C, TNNI3, and PPP6R1 (dense gene region). Via secondary review, not verified against the primary article.';

update known_safe_harbors set tissue_context = 'hESCs across multiple differentiation lineages; also used in HEK293 and hTERT-RPE1' where source_pmid = '41511364' and evidence_summary = 'Cytogenetic band 3p25.3 (hROSA26), intron 2 of THUMPD3. Stable expression in hESCs across multiple differentiation lineages; no silencing reported; used in HEK293 and hTERT-RPE1. Via secondary review, not verified against the primary article.';
