update known_safe_harbors set tissue_context = 'hiPSCs' where source_pmid = '41511364' and evidence_summary = 'Cytogenetic band 22q12.2, intergenic region between DRG1 and EIF4ENIF1. Stable expression of several transgenes in hiPSCs without silencing; supports recombinase-mediated cassette exchange (RMCE). Via secondary review, not verified against the primary article.';
update public_safe_harbors_staging set tissue_context = 'hiPSCs' where source_pmid = '41511364' and evidence_summary = 'Cytogenetic band 22q12.2, intergenic region between DRG1 and EIF4ENIF1. Stable expression of several transgenes in hiPSCs without silencing; supports recombinase-mediated cassette exchange (RMCE). Via secondary review, not verified against the primary article.';

update known_safe_harbors set tissue_context = 'Cell type not specified in evidence text (secondary-review-derived)' where source_pmid = '41511364' and evidence_summary = 'Cytogenetic band 3p21.31. Low probability of transgene expression, with gradual decline observed -- weak performance compared to AAVS1/ROSA26/H11/CLYBL. Upregulates flanking genes CCR1 and CCR3. Increases susceptibility to West Nile virus infection (the CCR5-delta32 mutation confers HIV resistance but carries this cost). Via secondary review, not verified against the primary article.';
update public_safe_harbors_staging set tissue_context = 'Cell type not specified in evidence text (secondary-review-derived)' where source_pmid = '41511364' and evidence_summary = 'Cytogenetic band 3p21.31. Low probability of transgene expression, with gradual decline observed -- weak performance compared to AAVS1/ROSA26/H11/CLYBL. Upregulates flanking genes CCR1 and CCR3. Increases susceptibility to West Nile virus infection (the CCR5-delta32 mutation confers HIV resistance but carries this cost). Via secondary review, not verified against the primary article.';

update known_safe_harbors set tissue_context = 'hiPSCs and neural stem cells' where source_pmid = '41511364' and evidence_summary = 'Cytogenetic band 13q32.1, intron 2 of the CLYBL gene itself. "Robust and superior" expression compared to AAVS1 in hiPSCs and neural stem cells. Minimal disruption of local gene expression (~50x reduction of CLYBL itself). No silencing reported; preserves pluripotency markers and differentiation capacity. Via secondary review, not verified against the primary article.';
update public_safe_harbors_staging set tissue_context = 'hiPSCs and neural stem cells' where source_pmid = '41511364' and evidence_summary = 'Cytogenetic band 13q32.1, intron 2 of the CLYBL gene itself. "Robust and superior" expression compared to AAVS1 in hiPSCs and neural stem cells. Minimal disruption of local gene expression (~50x reduction of CLYBL itself). No silencing reported; preserves pluripotency markers and differentiation capacity. Via secondary review, not verified against the primary article.';

update known_safe_harbors set tissue_context = 'Rhabdomyosarcoma cells; not yet tested in iPSCs' where source_pmid = '41511364' and evidence_summary = 'Cytogenetic band 4q13.1, intergenic, identified via pseudo-sites of the mCreI homing endonuclease. Robust integration and stable transgene expression for >45 days in rhabdomyosarcoma cells. Supports functional genome editing (Cas9 expression, PAX3/FOXO1 deletion). Not yet evaluated in iPSCs. Via secondary review, not verified against the primary article.';
update public_safe_harbors_staging set tissue_context = 'Rhabdomyosarcoma cells; not yet tested in iPSCs' where source_pmid = '41511364' and evidence_summary = 'Cytogenetic band 4q13.1, intergenic, identified via pseudo-sites of the mCreI homing endonuclease. Robust integration and stable transgene expression for >45 days in rhabdomyosarcoma cells. Supports functional genome editing (Cas9 expression, PAX3/FOXO1 deletion). Not yet evaluated in iPSCs. Via secondary review, not verified against the primary article.';

